import { LinearGradient } from 'expo-linear-gradient';
import { ImageBackground, StyleSheet, View, type StyleProp, type ViewStyle } from 'react-native';

// The warm plaster wall artwork hangs on in the memory detail screen
// (docs/plans/artwork-scanning-v2.md decision 5): flat plaster color, a faint
// tiling grain, and a diagonal window-light streak. Purely decorative; the
// content is passed as children and sits above it.
//
// The grain tile is generated by `scripts/generate-plaster-noise.py`.

export const GALLERY_WALL_COLOR = '#EEE3D3';
const NOISE_OPACITY = 0.09;
const LIGHT = 'rgba(255,249,236,0)';
const LIGHT_PEAK = 'rgba(255,249,236,0.6)';

interface GalleryWallProps {
  children?: React.ReactNode;
  style?: StyleProp<ViewStyle>;
  testID?: string;
}

export function GalleryWall({ children, style, testID }: GalleryWallProps) {
  return (
    <View style={[styles.wall, style]} testID={testID}>
      <View
        accessibilityElementsHidden
        importantForAccessibility="no-hide-descendants"
        pointerEvents="none"
        style={StyleSheet.absoluteFill}
      >
        <ImageBackground
          imageStyle={styles.noiseImage}
          resizeMode="repeat"
          source={require('../../../assets/textures/plaster-noise.png')}
          style={StyleSheet.absoluteFill}
          testID={testID ? `${testID}-noise` : undefined}
        />
        {/* ~120deg streak: light bleeding in from the upper left. */}
        <LinearGradient
          colors={[LIGHT, LIGHT_PEAK, LIGHT]}
          end={{ x: 1.3, y: 0.75 }}
          locations={[0.18, 0.34, 0.52]}
          start={{ x: -0.3, y: 0.25 }}
          style={StyleSheet.absoluteFill}
          testID={testID ? `${testID}-light` : undefined}
        />
      </View>
      {children}
    </View>
  );
}

const styles = StyleSheet.create({
  wall: {
    backgroundColor: GALLERY_WALL_COLOR,
    flex: 1,
    overflow: 'hidden',
  },
  noiseImage: {
    opacity: NOISE_OPACITY,
  },
});
